    return RemoteRef(
        remote="origin",
        ref="refs/heads/main",
        sha=REMOTE_SHA,
        read_at="2026-08-11T10:00:00Z",
    )


def _completed(returncode: int = 0, stdout: str = "", stderr: str = ""):
    return subprocess.CompletedProcess(
        args=[], returncode=returncode, stdout=stdout, stderr=stderr
