class TestRemoteIsTheSource:
    """The question is answered against the remote HEAD, never the clone."""

    def test_the_ref_and_sha_come_from_ls_remote(self, recorder):
        rec = recorder()
        ref = delivery.resolve_remote_head(Path("/repo"))

        assert rec.git_calls[0] == [
            "git",
            "ls-remote",
            "--symref",
            "origin",
            "HEAD",
        ]
        assert ref.sha == REMOTE_SHA
        assert ref.ref == "refs/heads/main"
        assert ref.remote == "origin"

    def test_the_instant_is_recorded(self, recorder):
        recorder()
        ref = delivery.resolve_remote_head(Path("/repo"))
        # A total is a claim about one moment; the label carries it.
        assert ref.read_at.endswith("Z")
        assert ref.read_at in ref.label
        assert ref.sha[:12] in ref.label

    def test_an_unreachable_remote_is_not_an_empty_scoreboard(
        self, recorder, tmp_path
    ):
        _signal(tmp_path, tasks=[{"name": "t1"}])
        recorder(ls_remote_code=1, ls_remote="fatal: could not read")

        with pytest.raises(RegentError, match="could not reach origin"):
            delivery.score_signal(
                tmp_path, "idea-x", source_dir=tmp_path
            )

    def test_no_read_ever_names_a_local_ref(self, recorder, tmp_path):
        """Every content read is pinned to the sha ls-remote returned.

        This is the assertion the two wrong scoreboards would have
        failed: no command in the sequence resolves `main`, `HEAD` or
        `origin/main` locally, so a checkout eight commits behind cannot
        change the answer.
        """
        _signal(tmp_path, tasks=[{"name": "t1"}])
        rec = recorder()
        delivery.score_signal(tmp_path, "idea-x", source_dir=tmp_path)

        content_reads = [
            c
            for c in rec.git_calls
            if c[1] in ("show", "log", "merge-base", "cat-file")
        ]
        assert content_reads, "nothing read the diff at all"
        for call in content_reads:
            for arg in call[2:]:
                assert arg not in ("main", "HEAD", "origin/main", "master")
                assert not arg.startswith("origin/")
        # And the remote sha is what ancestry is measured against.
        merge_base = [c for c in rec.git_calls if c[1] == "merge-base"][0]
        assert REMOTE_SHA in merge_base

    def test_a_ref_name_is_structurally_refused(self):
        for name in ("main", "HEAD", "origin/main", "", LOCAL_SHA[:8]):
            with pytest.raises(RegentError, match="refusing to read"):
                delivery._require_sha(name)
        assert delivery._require_sha(REMOTE_SHA.upper()) == REMOTE_SHA

